// Comparison-only executable: original fixture bodies and frozen vectors are
// inputs, never generated by CS2PS. The candidate runs in a dotnet-only process.
using System;
using System.Globalization;
using System.IO;
using System.Reflection;
using System.Text.Json;

public static class ConsumerOracle
{
    static bool HasSma()
    {
        foreach (var assembly in AppDomain.CurrentDomain.GetAssemblies())
            if (assembly.GetName().Name == "System.Management.Automation") return true;
        return false;
    }

    static object Input(JsonElement element, Type type)
    {
        if (element.ValueKind == JsonValueKind.Null) return null;
        if (type == typeof(object))
        {
            if (element.ValueKind == JsonValueKind.String) return element.GetString();
            if (element.ValueKind == JsonValueKind.Number) return element.GetInt32();
            if (element.ValueKind == JsonValueKind.True) return true;
            if (element.ValueKind == JsonValueKind.False) return false;
            throw new NotSupportedException("Unadmitted object input");
        }
        return JsonSerializer.Deserialize(element.GetRawText(), type);
    }

    static (object Value, Type Error) Invoke(MethodInfo method, object[] values)
    {
        try { return (method.Invoke(null, values), null); }
        catch (TargetInvocationException exception) { return (null, exception.InnerException.GetType()); }
    }

    public static int Main(string[] args)
    {
        if (HasSma()) return 3;
        CultureInfo.CurrentCulture = CultureInfo.GetCultureInfo(args[2]);
        var candidate = Assembly.LoadFrom(Path.GetFullPath(args[0])).GetType(args[1], true);
        var original = typeof(ConsumerOracle).Assembly.GetType(args[1], true);
        var admitted = ("|" + args[4] + "|");
        using var vectors = JsonDocument.Parse(File.ReadAllText(args[3]));
        int calls = 0, differences = 0;
        foreach (var vector in vectors.RootElement.EnumerateArray())
        {
            string name = vector.GetProperty("Method").GetString();
            if (!admitted.Contains("|" + name + "|", StringComparison.Ordinal)) continue;
            const BindingFlags flags = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static;
            var expectedMethod = original.GetMethod(name, flags);
            var actualMethod = candidate.GetMethod(name, flags);
            var parameters = expectedMethod.GetParameters();
            var values = new object[parameters.Length];
            var arguments = vector.GetProperty("Arguments");
            for (int i = 0; i < values.Length; i++) values[i] = Input(arguments[i], parameters[i].ParameterType);
            var expected = Invoke(expectedMethod, values);
            var actual = Invoke(actualMethod, values);
            if (expected.Error != actual.Error || expected.Value?.GetType() != actual.Value?.GetType()
                || !object.Equals(expected.Value, actual.Value)) differences++;
            calls++;
        }
        if (HasSma()) return 3;
        Console.WriteLine($"calls {calls}, differences {differences}, SMA absent");
        return calls == 0 || differences != 0 ? 1 : 0;
    }
}
